#include <stdio.h>
#include <string.h>

/* row of column t for k rails */
static int rail(int t, int k)
{
    if (k == 1)
        return 0;                   /* avoid t % 0 */
    int p = 2 * (k - 1);            /* period of the zig-zag */
    int m = t % p;
    return m < k ? m : p - m;       /* going down, then coming back up */
}

int main(void)
{
    int k;
    char s[101];
    if (scanf("%d", &k) != 1 || scanf("%100s", s) != 1) return 0;

    if (k < 1) {
        printf("INVALID\n");
        return 0;
    }
    int len = (int)strlen(s);

    for (int r = 0; r < k; r++) {
        int last = -1;                          /* last column used in this row */
        for (int t = 0; t < len; t++)
            if (rail(t, k) == r)
                last = t;
        for (int t = 0; t <= last; t++)         /* no trailing spaces */
            putchar(rail(t, k) == r ? s[t] : ' ');
        putchar('\n');
    }

    printf("CIPHER: ");
    for (int r = 0; r < k; r++)
        for (int t = 0; t < len; t++)
            if (rail(t, k) == r)
                putchar(s[t]);
    putchar('\n');
    return 0;
}

