#include <stdio.h>
#include <string.h>

#define MAXCELLS 64

static int level[MAXCELLS];
static char label[MAXCELLS][3];     /* "" for idle cells */
static int ncells;

static void add(int v, const char *lab, int idx)
{
    level[ncells] = v;
    if (idx >= 0) {                 /* data bit label D0..D7 */
        label[ncells][0] = 'D';
        label[ncells][1] = (char)('0' + idx);
        label[ncells][2] = '\0';
    } else {
        strcpy(label[ncells], lab);
    }
    ncells++;
}

int main(void)
{
    char cfg[16];
    int k;
    if (scanf("%15s", cfg) != 1) return 0;

    if (strlen(cfg) != 3 || cfg[0] < '5' || cfg[0] > '8' ||
        (cfg[1] != 'N' && cfg[1] != 'E' && cfg[1] != 'O') ||
        (cfg[2] != '1' && cfg[2] != '2')) {
        printf("BAD CONFIG\n");
        return 0;
    }
    int d = cfg[0] - '0';
    char par = cfg[1];
    int stop = cfg[2] - '0';

    if (scanf("%d", &k) != 1) return 0;
    if (k < 1 || k > 4) {
        printf("BAD LENGTH\n");
        return 0;
    }

    add(1, "", -1);                                 /* idle before */
    for (int f = 0; f < k; f++) {
        unsigned int b;
        if (scanf("%x", &b) != 1) return 0;
        int ones = 0;
        add(0, "ST", -1);                           /* start bit */
        for (int i = 0; i < d; i++) {               /* LSB first */
            int bit = (int)((b >> i) & 1u);
            ones += bit;
            add(bit, "", i);
        }
        if (par == 'E')
            add(ones % 2, "PA", -1);                /* makes the count even */
        else if (par == 'O')
            add(1 - ones % 2, "PA", -1);            /* makes the count odd */
        for (int s = 0; s < stop; s++)
            add(1, "SP", -1);
    }
    add(1, "", -1);                                 /* idle after */

    for (int row = 0; row < 4; row++) {
        int prev = 1;                               /* line was idle (high) */
        for (int c = 0; c < ncells; c++) {
            int v = level[c];
            int edge = (v != prev);
            if (row == 0) {
                putchar(edge ? ' ' : (v ? '_' : ' '));
                printf(v ? "__" : "  ");
            } else if (row == 1) {
                putchar(edge ? '|' : (v ? ' ' : '_'));
                printf(v ? "  " : "__");
            } else if (row == 2) {
                printf(label[c][0] ? " %s" : "   ", label[c]);
            } else {
                if (label[c][0])
                    printf("  %d", v);
                else
                    printf("   ");
            }
            prev = v;
        }
        putchar('\n');
    }
    printf("frames=%d bits/frame=%d\n", k, 1 + d + (par != 'N') + stop);
    return 0;
}

