        if (scanf("%x %d", &id, &dlc) != 2 || dlc < 0 || dlc > 8) return 0;
        for (int i = 0; i < dlc; i++) {
            unsigned int tmp;
            if (scanf("%x", &tmp) != 1) return 0;
            data[i] = tmp;
        }

