        int sum = 0;
        for (int i = 0; i < dlc; i++) {
            printf("  B%d 0x%c%c %3d ", i,
                   HEX[(data[i] >> 4) & 0x0F], HEX[data[i] & 0x0F], data[i]);
            for (int b = 7; b >= 0; b--)
                putchar(((data[i] >> b) & 1) ? '*' : '.');
            putchar('\n');
            sum += data[i];
        }
        printf("  SUM %d\n", sum);
    }
    return 0;
}

