#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    long long total;
    int width, k;
    if (scanf("%lld %d", &total, &width) != 2) return 0;
    if (total < 1 || width < 1 || width > 60) {
        printf("ERR\n");
        return 0;
    }
    if (scanf("%d", &k) != 1) return 0;

    size_t cap = (size_t)width + 24;        /* '[' + bar + ']' + status text */
    char *line = malloc(cap);
    if (!line) return 1;

    for (int u = 0; u < k; u++) {
        long long written;
        if (scanf("%lld", &written) != 1) break;
        if (written > total)
            written = total;

        int pct = (int)(written * 100 / total);
        int filled = (int)(written * width / total);

        int pos = 0;
        line[pos++] = '[';
        for (int i = 0; i < width; i++)
            line[pos++] = (i < filled) ? '#' : '.';
        line[pos++] = ']';
        sprintf(line + pos, " %3d%% (%lld/%lld)", pct, written, total);
        puts(line);
    }
    free(line);
    return 0;
}

